// Retrieve persistent static workflow data
const staticData = \$getWorkflowStaticData('global');
const lastExecution = staticData.lastExecutionTimestamp || 0;
const now = Date.now();
const oneDayMs = 24 * 60 * 60 * 1000;

// Default initial lookback: 7 days ago if first run
const initialLookback = now - (7 * 24 * 60 * 60 * 1000); 
const fetchFromTime = lastExecution > 0 ? lastExecution : initialLookback;

if (lastExecution && (now - lastExecution < oneDayMs)) {
  const hoursLeft = ((oneDayMs - (now - lastExecution)) / (1000 * 60 * 60)).toFixed(2);
  throw new Error(`Execution blocked: Less than 24 hours since last run. Try again in ${hoursLeft} hours.`);
}

return [{
  json: {
    canExecute: true,
    fetchFromTime: Math.floor(fetchFromTime / 1000), // Convert to Unix Timestamp (seconds)
    executionTime: now
  }
}];

const items = \$input.all();
const fetchFromTime = \$('Code').first().json.fetchFromTime;
const targetChannelId = "-100XXXXXXXXXX"; // Replace with Source Channel Chat ID

let cleanedMessages = [];

for (const item of items) {
  const result = item.json.result || [];
  for (const update of result) {
    const post = update.channel_post || update.message;

    if (post && String(post.chat.id) === targetChannelId) {
      if (post.date >= fetchFromTime && post.text) {
        const sender = post.from ? (post.from.username || post.from.first_name) : 'Channel Post';
        const dateStr = new Date(post.date * 1000).toISOString();

        cleanedMessages.push({
          timestamp: post.date,
          formattedDate: dateStr,
          person: sender,
          text: post.text.trim()
        });
      }
    }
  }
}

// Sort chronologically (oldest to newest)
cleanedMessages.sort((a, b) => a.timestamp - b.timestamp);

// Format as a single clean transcript block
const formattedTranscript = cleanedMessages
  .map(m => `[${m.formattedDate}] ${m.person}: ${m.text}`)
  .join('\n');

return [{
  json: {
    hasMessages: cleanedMessages.length > 0,
    transcript: formattedTranscript,
    messageCount: cleanedMessages.length
  }
}];

const text = $input.first().json.text || $input.first().json.response;
const maxLength = 32000; // Safe threshold under Telegram's limit
const chunks = [];

if (text.length <= maxLength) {
  chunks.push(text);
} else {
  let position = 0;
  while (position < text.length) {
    let chunk = text.substring(position, position + maxLength);
    // Break at last newline to avoid breaking mid-sentence
    let breakPoint = chunk.lastIndexOf('\n');
    if (breakPoint > -1 && position + maxLength < text.length) {
      chunk = chunk.substring(0, breakPoint);
      position += breakPoint + 1;
    } else {
      position += maxLength;
    }
    chunks.push(chunk);
  }
}

return chunks.map((chunk, index) => ({
  json: {
    chunkText: chunk,
    part: index + 1,
    totalParts: chunks.length
  }
}));

const staticData = $getWorkflowStaticData('global');
const executionTime = $('Code').first().json.executionTime;

// Persist execution time across manual runs
staticData.lastExecutionTimestamp = executionTime;

return [{
  json: {
    status: "Success",
    savedTimestamp: executionTime,
    dateTime: new Date(executionTime).toISOString()
  }
}];
